contracts/TestToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title TestToken: a plain ERC-20 for the ZETAPHY testnet DEX (no value, testnet only).
/// @notice The deployer gets the initial supply and may mint more (a test faucet).
///         Optional `feeBps`: a cut of every transfer is burned (fee-on-transfer
///         token, to test the router's *SupportingFeeOnTransferTokens functions).
contract TestToken {
    string public name;
    string public symbol;
    uint8 public immutable decimals;
    uint16 public immutable feeBps;
    address public immutable minter;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    error InsufficientBalance();
    error InsufficientAllowance();
    error NotMinter();

    constructor(string memory name_, string memory symbol_, uint8 decimals_, uint256 initialSupply, uint16 feeBps_) {
        require(feeBps_ <= 5000, "fee");
        name = name_;
        symbol = symbol_;
        decimals = decimals_;
        feeBps = feeBps_;
        minter = msg.sender;
        _mint(msg.sender, initialSupply);
    }

    function mint(address to, uint256 value) external {
        if (msg.sender != minter) revert NotMinter();
        _mint(to, value);
    }

    function _mint(address to, uint256 value) private {
        totalSupply += value;
        unchecked { balanceOf[to] += value; }
        emit Transfer(address(0), to, value);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - value; }
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        uint256 b = balanceOf[from];
        if (b < value) revert InsufficientBalance();
        uint256 fee = (value * feeBps) / 10_000;
        unchecked {
            balanceOf[from] = b - value;
            balanceOf[to] += value - fee;
            totalSupply -= fee;
        }
        emit Transfer(from, to, value - fee);
        if (fee != 0) emit Transfer(from, address(0), fee);
    }
}

contracts/WZETAPHY.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title WZETAPHY: wrapped native coin, one token per wei (a classic WETH, written from scratch).
/// @notice On ZETAPHY itself the DEX uses the native ERC-20 precompile
///         0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE instead (Cosmos EVM's WERC20,
///         whose balances ARE the native balances). This contract is for the
///         unit tests (an EVM without that precompile) and for other EVM chains:
///         `cli.js deploy --wnative deploy` deploys it.
contract WZETAPHY {
    string public constant name = "Wrapped ZETAPHY";
    string public constant symbol = "WZTPHY";
    uint8 public constant decimals = 18;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Transfer(address indexed from, address indexed to, uint256 value);
    event Deposit(address indexed to, uint256 value);
    event Withdrawal(address indexed from, uint256 value);

    error InsufficientBalance();
    error InsufficientAllowance();
    error SendFailed();

    receive() external payable {
        deposit();
    }

    function deposit() public payable {
        balanceOf[msg.sender] += msg.value;
        emit Deposit(msg.sender, msg.value);
    }

    function withdraw(uint256 value) external {
        if (balanceOf[msg.sender] < value) revert InsufficientBalance();
        unchecked { balanceOf[msg.sender] -= value; }
        emit Withdrawal(msg.sender, value);
        (bool ok,) = msg.sender.call{value: value}("");
        if (!ok) revert SendFailed();
    }

    function totalSupply() external view returns (uint256) {
        return address(this).balance;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        return transferFrom(msg.sender, to, value);
    }

    function transferFrom(address from, address to, uint256 value) public returns (bool) {
        if (balanceOf[from] < value) revert InsufficientBalance();
        if (from != msg.sender) {
            uint256 a = allowance[from][msg.sender];
            if (a != type(uint256).max) {
                if (a < value) revert InsufficientAllowance();
                unchecked { allowance[from][msg.sender] = a - value; }
            }
        }
        unchecked {
            balanceOf[from] -= value;
            balanceOf[to] += value;
        }
        emit Transfer(from, to, value);
        return true;
    }
}

contracts/ZetaphyFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

import {ZetaphyPair} from "./ZetaphyPair.sol";

/// The part of Neuro's ThreatRegistry (zetaphy-network/contracts/ThreatRegistry.sol)
/// the DEX reads: true once a flag on the contract's address on this chain, or
/// on its exact code (extcodehash), is enforced. Reason: ThreatRegistry.Reason.
interface IThreatRegistryView {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

/// @title ZetaphyFactory: creates one ZetaphyPair per token pair (CREATE2) and
///        holds the DEX's governance settings.
/// @notice Governance (a multisig on the testnet) may:
///           - setFeeTo(a):           the protocol fee switch. Zero (the default) = off;
///                                    otherwise 1/6 of the 0.3% LP fee goes to `a` as LP tokens;
///           - setThreatRegistry(r):  Neuro's ThreatRegistry. Zero (the default) = off;
///                                    otherwise the router refuses to swap into, or add
///                                    liquidity with, a token whose flag is ENFORCED there.
///                                    Selling a token and removing liquidity always work;
///           - transfer governance (two steps: setGovernance, then acceptGovernance).
///         Governance cannot move anyone's funds, pause pools or change the 0.3% fee.
contract ZetaphyFactory {
    address public governance;
    address public pendingGovernance;
    address public feeTo;
    address public threatRegistry;

    mapping(address => mapping(address => address)) public getPair;
    address[] public allPairs;

    /// keccak256 of ZetaphyPair's creation code: pair = CREATE2(this, keccak256(token0, token1), PAIR_CODE_HASH).
    bytes32 public immutable PAIR_CODE_HASH;

    address private _p0;
    address private _p1;

    event PairCreated(address indexed token0, address indexed token1, address pair, uint256 allPairsLength);
    event FeeToSet(address feeTo);
    event ThreatRegistrySet(address registry);
    event GovernanceProposed(address governance);
    event GovernanceSet(address governance);

    error IdenticalAddresses();
    error ZeroAddress();
    error PairExists();
    error NotGovernance();
    error NotPendingGovernance();
    error NotARegistry();

    modifier onlyGov() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    constructor(address governance_) {
        if (governance_ == address(0)) revert ZeroAddress();
        governance = governance_;
        PAIR_CODE_HASH = keccak256(type(ZetaphyPair).creationCode);
        emit GovernanceSet(governance_);
    }

    function allPairsLength() external view returns (uint256) {
        return allPairs.length;
    }

    /// Read by a new pair's constructor (only set during createPair).
    function pairParameters() external view returns (address token0, address token1) {
        return (_p0, _p1);
    }

    function createPair(address tokenA, address tokenB) external returns (address pair) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert ZeroAddress();
        if (getPair[token0][token1] != address(0)) revert PairExists();
        _p0 = token0;
        _p1 = token1;
        pair = address(new ZetaphyPair{salt: keccak256(abi.encodePacked(token0, token1))}());
        delete _p0;
        delete _p1;
        getPair[token0][token1] = pair;
        getPair[token1][token0] = pair;
        allPairs.push(pair);
        emit PairCreated(token0, token1, pair, allPairs.length);
    }

    function setFeeTo(address feeTo_) external onlyGov {
        feeTo = feeTo_;
        emit FeeToSet(feeTo_);
    }

    /// Zero switches the router's check off. A nonzero address must answer
    /// isContractEnforced (checked here), so a typo cannot stop every swap.
    function setThreatRegistry(address registry) external onlyGov {
        if (registry != address(0)) {
            (bool ok, bytes memory r) = registry.staticcall(abi.encodeCall(IThreatRegistryView.isContractEnforced, (address(this))));
            if (!ok || r.length < 64) revert NotARegistry();
        }
        threatRegistry = registry;
        emit ThreatRegistrySet(registry);
    }

    function setGovernance(address next) external onlyGov {
        pendingGovernance = next;
        emit GovernanceProposed(next);
    }

    function acceptGovernance() external {
        if (msg.sender != pendingGovernance) revert NotPendingGovernance();
        governance = msg.sender;
        pendingGovernance = address(0);
        emit GovernanceSet(msg.sender);
    }
}

contracts/ZetaphyPair.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY DEX pair: a constant-product (x * y = k) pool of two tokens, written
// from scratch for ZETAPHY (MIT). The math and the interface follow the
// Uniswap V2 whitepaper (https://uniswap.org/whitepaper.pdf) so that tools
// that know V2 pools read it too, but no Uniswap source code is copied.
//
//   - fee: 0.3% of every input stays in the pool (LP fee);
//   - protocol fee: off by default. When governance sets factory.feeTo, 1/6
//     of the fee growth (0.05% of volume) is minted to feeTo as LP tokens,
//     on the next mint/burn (whitepaper section 2.4);
//   - TWAP: price0CumulativeLast / price1CumulativeLast accumulate the
//     UQ112.112 price times seconds, at the first touch of each block, before
//     the trade (overflow is intended: consumers take differences);
//   - MINIMUM_LIQUIDITY (1000 wei of LP) is locked at address(0) on the first
//     mint, so the share price can never be pushed to a level where nobody
//     can afford a share;
//   - every state-changing function holds one reentrancy lock;
//   - skim() sends out tokens above the reserves, sync() sets the reserves
//     to the balances;
//   - flash swaps: swap() sends the output first and, with data, calls
//     zetaphyDexCall on `to`; the K check after it needs the input (or the
//     output back plus the fee) to be in the pool by then.

interface IZetaphyFactoryForPair {
    function feeTo() external view returns (address);
    function pairParameters() external view returns (address token0, address token1);
}

interface IERC20Balance {
    function balanceOf(address) external view returns (uint256);
}

interface IZetaphyDexCallee {
    function zetaphyDexCall(address sender, uint256 amount0Out, uint256 amount1Out, bytes calldata data) external;
}

contract ZetaphyPair {
    // ---- LP token (ERC-20) ----
    string public constant name = "ZETAPHY DEX LP";
    string public constant symbol = "ZLP";
    uint8 public constant decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    // ---- pool ----
    uint256 public constant MINIMUM_LIQUIDITY = 1000;
    address public immutable factory;
    address public immutable token0;
    address public immutable token1;

    uint112 private reserve0;
    uint112 private reserve1;
    uint32 private blockTimestampLast;

    uint256 public price0CumulativeLast;
    uint256 public price1CumulativeLast;
    /// reserve0 * reserve1 after the last liquidity event (only kept while the protocol fee is on).
    uint256 public kLast;

    uint256 private unlocked = 1;

    event Mint(address indexed sender, uint256 amount0, uint256 amount1);
    event Burn(address indexed sender, uint256 amount0, uint256 amount1, address indexed to);
    event Swap(address indexed sender, uint256 amount0In, uint256 amount1In, uint256 amount0Out, uint256 amount1Out, address indexed to);
    event Sync(uint112 reserve0, uint112 reserve1);

    error Locked();
    error Overflow();
    error TransferFailed();
    error InsufficientLiquidityMinted();
    error InsufficientLiquidityBurned();
    error InsufficientOutputAmount();
    error InsufficientInputAmount();
    error InsufficientLiquidity();
    error InvalidTo();
    error K();
    error InsufficientAllowance();
    error InsufficientBalance();

    modifier lock() {
        if (unlocked != 1) revert Locked();
        unlocked = 2;
        _;
        unlocked = 1;
    }

    /// Created by the factory with CREATE2; the tokens come from the factory,
    /// so the init code (and so every pair's address) does not depend on them.
    constructor() {
        factory = msg.sender;
        (token0, token1) = IZetaphyFactoryForPair(msg.sender).pairParameters();
    }

    function getReserves() public view returns (uint112 _reserve0, uint112 _reserve1, uint32 _blockTimestampLast) {
        _reserve0 = reserve0;
        _reserve1 = reserve1;
        _blockTimestampLast = blockTimestampLast;
    }

    // ---- ERC-20 ----

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 a = allowance[from][msg.sender];
        if (a != type(uint256).max) {
            if (a < value) revert InsufficientAllowance();
            unchecked { allowance[from][msg.sender] = a - value; }
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        uint256 b = balanceOf[from];
        if (b < value) revert InsufficientBalance();
        unchecked {
            balanceOf[from] = b - value;
            balanceOf[to] += value; // cannot overflow: sum of balances == totalSupply
        }
        emit Transfer(from, to, value);
    }

    function _mint(address to, uint256 value) private {
        totalSupply += value;
        unchecked { balanceOf[to] += value; }
        emit Transfer(address(0), to, value);
    }

    function _burn(address from, uint256 value) private {
        balanceOf[from] -= value;
        unchecked { totalSupply -= value; }
        emit Transfer(from, address(0), value);
    }

    // ---- pool internals ----

    /// transfer(), accepting tokens that return nothing (USDT-style) but not ones that return false.
    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _balance(address token) private view returns (uint256) {
        return IERC20Balance(token).balanceOf(address(this));
    }

    /// New reserves; on the block's first touch, the price accumulators grow by
    /// the price before this update times the seconds since the last one.
    function _update(uint256 balance0, uint256 balance1, uint112 _reserve0, uint112 _reserve1) private {
        if (balance0 > type(uint112).max || balance1 > type(uint112).max) revert Overflow();
        uint32 blockTimestamp = uint32(block.timestamp % 2 ** 32);
        unchecked {
            uint32 timeElapsed = blockTimestamp - blockTimestampLast; // wraps around, by design
            if (timeElapsed > 0 && _reserve0 != 0 && _reserve1 != 0) {
                // UQ112.112: (reserve1 << 112) / reserve0 fits in 224 bits; the products wrap, by design.
                price0CumulativeLast += ((uint256(_reserve1) << 112) / _reserve0) * timeElapsed;
                price1CumulativeLast += ((uint256(_reserve0) << 112) / _reserve1) * timeElapsed;
            }
        }
        reserve0 = uint112(balance0);
        reserve1 = uint112(balance1);
        blockTimestampLast = blockTimestamp;
        emit Sync(reserve0, reserve1);
    }

    /// Protocol fee: 1/6 of the growth of sqrt(k) since the last liquidity event, as LP tokens to feeTo.
    function _mintFee(uint112 _reserve0, uint112 _reserve1) private returns (bool feeOn) {
        address feeTo = IZetaphyFactoryForPair(factory).feeTo();
        feeOn = feeTo != address(0);
        uint256 _kLast = kLast;
        if (feeOn) {
            if (_kLast != 0) {
                uint256 rootK = _sqrt(uint256(_reserve0) * _reserve1);
                uint256 rootKLast = _sqrt(_kLast);
                if (rootK > rootKLast) {
                    uint256 liquidity = (totalSupply * (rootK - rootKLast)) / (rootK * 5 + rootKLast);
                    if (liquidity > 0) _mint(feeTo, liquidity);
                }
            }
        } else if (_kLast != 0) {
            kLast = 0;
        }
    }

    // ---- pool: called by the router (or anyone who transferred tokens in first) ----

    /// LP tokens for the tokens sent to the pair since the last update.
    function mint(address to) external lock returns (uint256 liquidity) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        uint256 balance0 = _balance(token0);
        uint256 balance1 = _balance(token1);
        uint256 amount0 = balance0 - _reserve0;
        uint256 amount1 = balance1 - _reserve1;

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply; // after _mintFee, which may change it
        if (_totalSupply == 0) {
            uint256 root = _sqrt(amount0 * amount1);
            if (root <= MINIMUM_LIQUIDITY) revert InsufficientLiquidityMinted();
            liquidity = root - MINIMUM_LIQUIDITY;
            _mint(address(0), MINIMUM_LIQUIDITY); // locked forever
        } else {
            uint256 l0 = (amount0 * _totalSupply) / _reserve0;
            uint256 l1 = (amount1 * _totalSupply) / _reserve1;
            liquidity = l0 < l1 ? l0 : l1;
        }
        if (liquidity == 0) revert InsufficientLiquidityMinted();
        _mint(to, liquidity);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Mint(msg.sender, amount0, amount1);
    }

    /// Burns the LP tokens sent to the pair; their share of both tokens goes to `to`.
    function burn(address to) external lock returns (uint256 amount0, uint256 amount1) {
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        address _token0 = token0;
        address _token1 = token1;
        uint256 balance0 = _balance(_token0);
        uint256 balance1 = _balance(_token1);
        uint256 liquidity = balanceOf[address(this)];

        bool feeOn = _mintFee(_reserve0, _reserve1);
        uint256 _totalSupply = totalSupply;
        amount0 = (liquidity * balance0) / _totalSupply; // pro rata of balances, not reserves
        amount1 = (liquidity * balance1) / _totalSupply;
        if (amount0 == 0 || amount1 == 0) revert InsufficientLiquidityBurned();
        _burn(address(this), liquidity);
        _safeTransfer(_token0, to, amount0);
        _safeTransfer(_token1, to, amount1);
        balance0 = _balance(_token0);
        balance1 = _balance(_token1);

        _update(balance0, balance1, _reserve0, _reserve1);
        if (feeOn) kLast = uint256(reserve0) * reserve1;
        emit Burn(msg.sender, amount0, amount1, to);
    }

    /// Sends the outputs to `to` (then calls it back if `data` is not empty);
    /// the inputs must be in the pair by the end, such that the balances less
    /// 0.3% of the inputs keep k at least where it was.
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external lock {
        if (amount0Out == 0 && amount1Out == 0) revert InsufficientOutputAmount();
        (uint112 _reserve0, uint112 _reserve1,) = getReserves();
        if (amount0Out >= _reserve0 || amount1Out >= _reserve1) revert InsufficientLiquidity();

        uint256 balance0;
        uint256 balance1;
        {
            address _token0 = token0;
            address _token1 = token1;
            if (to == _token0 || to == _token1) revert InvalidTo();
            if (amount0Out > 0) _safeTransfer(_token0, to, amount0Out); // optimistic
            if (amount1Out > 0) _safeTransfer(_token1, to, amount1Out);
            if (data.length > 0) IZetaphyDexCallee(to).zetaphyDexCall(msg.sender, amount0Out, amount1Out, data);
            balance0 = _balance(_token0);
            balance1 = _balance(_token1);
        }
        uint256 amount0In = balance0 > _reserve0 - amount0Out ? balance0 - (_reserve0 - amount0Out) : 0;
        uint256 amount1In = balance1 > _reserve1 - amount1Out ? balance1 - (_reserve1 - amount1Out) : 0;
        if (amount0In == 0 && amount1In == 0) revert InsufficientInputAmount();
        {
            uint256 balance0Adjusted = balance0 * 1000 - amount0In * 3;
            uint256 balance1Adjusted = balance1 * 1000 - amount1In * 3;
            if (balance0Adjusted * balance1Adjusted < uint256(_reserve0) * _reserve1 * 1_000_000) revert K();
        }

        _update(balance0, balance1, _reserve0, _reserve1);
        emit Swap(msg.sender, amount0In, amount1In, amount0Out, amount1Out, to);
    }

    /// Sends whatever is above the reserves (e.g. tokens sent by mistake) to `to`.
    function skim(address to) external lock {
        address _token0 = token0;
        address _token1 = token1;
        _safeTransfer(_token0, to, _balance(_token0) - reserve0);
        _safeTransfer(_token1, to, _balance(_token1) - reserve1);
    }

    /// Sets the reserves to the balances (e.g. after a token's balance changed on its own).
    function sync() external lock {
        _update(_balance(token0), _balance(token1), reserve0, reserve1);
    }

    function _sqrt(uint256 y) private pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/ZetaphyRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

// ZETAPHY DEX router (MIT, written from scratch). The functions keep the
// Uniswap V2 router's names and argument order, so wallets that decode V2
// calls show them; "ETH" in a name means the chain's native coin (ZETAPHY,
// ticker ZTPHY), which the router wraps through WETH():
//   - on ZETAPHY: the native ERC-20 precompile 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE
//     (Cosmos EVM's WERC20: its balanceOf is the native balance, transfer moves
//     native coins, deposit() gives the coins straight back, withdraw() is a no-op);
//   - elsewhere (and in the unit tests): the WZETAPHY contract, a classic WETH.
// The router works with both, because it only relies on deposit, withdraw,
// transfer and balanceOf.
//
// Every function checks a deadline; every swap and liquidity call takes a
// minimum (or maximum) amount, so the caller sets the slippage it accepts.
// The *SupportingFeeOnTransferTokens functions work with tokens that take a
// cut on transfer: they measure what each pair actually received.
//
// Neuro: when governance set factory.threatRegistry() (zero = off), the
// router refuses to swap INTO, or add liquidity with, a token whose flag is
// enforced in Neuro's ThreatRegistry (isContractEnforced: the token's address
// on this chain, or its exact code). Selling such a token and removing
// liquidity always work, so nobody is locked in. A flag is automated,
// reproducible code analysis, not an accusation (docs/LEGAL.md).

interface IFactory {
    function getPair(address, address) external view returns (address);
    function createPair(address, address) external returns (address);
    function threatRegistry() external view returns (address);
    function PAIR_CODE_HASH() external view returns (bytes32);
}

interface IPair {
    function getReserves() external view returns (uint112, uint112, uint32);
    function mint(address to) external returns (uint256);
    function burn(address to) external returns (uint256, uint256);
    function swap(uint256 amount0Out, uint256 amount1Out, address to, bytes calldata data) external;
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IWNative {
    function deposit() external payable;
    function withdraw(uint256) external;
}

interface IERC20Min {
    function balanceOf(address) external view returns (uint256);
}

interface IThreatView {
    function isContractEnforced(address who) external view returns (bool enforced, uint8 reason);
}

contract ZetaphyRouter {
    address public immutable factory;
    address public immutable WETH;
    bytes32 private immutable pairCodeHash;

    error Expired();
    error InvalidPath();
    error InsufficientAAmount();
    error InsufficientBAmount();
    error InsufficientAmount();
    error InsufficientLiquidity();
    error InsufficientInputAmount();
    error InsufficientOutputAmount();
    error ExcessiveInputAmount();
    error IdenticalAddresses();
    error ZeroAddress();
    error TransferFailed();
    error NativeTransferFailed();
    error OnlyWNative();
    /// Neuro's ThreatRegistry has an enforced flag on this token (reason: ThreatRegistry.Reason).
    error TokenEnforced(address token, uint8 reason);
    /// The ThreatRegistry governance set did not answer; fails closed.
    error RegistryUnavailable();

    modifier ensure(uint256 deadline) {
        if (deadline < block.timestamp) revert Expired();
        _;
    }

    constructor(address factory_, address wnative) {
        if (factory_ == address(0) || wnative == address(0)) revert ZeroAddress();
        factory = factory_;
        WETH = wnative;
        pairCodeHash = IFactory(factory_).PAIR_CODE_HASH();
    }

    /// Native coins only come from WZETAPHY.withdraw (the precompile moves them without a call).
    receive() external payable {
        if (msg.sender != WETH) revert OnlyWNative();
    }

    // ---- Neuro ----

    /// Reverts with TokenEnforced if the registry (when set) has an enforced flag on `token`.
    function _refuseEnforced(address registry, address token) private view {
        if (token == WETH) return;
        (bool ok, bytes memory r) = registry.staticcall(abi.encodeCall(IThreatView.isContractEnforced, (token)));
        if (!ok || r.length < 64) revert RegistryUnavailable();
        (bool enforced, uint8 reason) = abi.decode(r, (bool, uint8));
        if (enforced) revert TokenEnforced(token, reason);
    }

    /// Every token a swap along `path` receives into a pool or hands out (path[1..]); not the one sold.
    function _checkPath(address[] calldata path) private view {
        address registry = IFactory(factory).threatRegistry();
        if (registry == address(0)) return;
        for (uint256 i = 1; i < path.length; i++) _refuseEnforced(registry, path[i]);
    }

    function _checkPair(address a, address b) private view {
        address registry = IFactory(factory).threatRegistry();
        if (registry == address(0)) return;
        _refuseEnforced(registry, a);
        _refuseEnforced(registry, b);
    }

    // ---- library ----

    function sortTokens(address tokenA, address tokenB) public pure returns (address token0, address token1) {
        if (tokenA == tokenB) revert IdenticalAddresses();
        (token0, token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        if (token0 == address(0)) revert ZeroAddress();
    }

    /// The pair's CREATE2 address (it may not exist yet).
    function pairFor(address tokenA, address tokenB) public view returns (address) {
        (address token0, address token1) = sortTokens(tokenA, tokenB);
        return address(uint160(uint256(keccak256(abi.encodePacked(
            hex"ff", factory, keccak256(abi.encodePacked(token0, token1)), pairCodeHash)))));
    }

    function getReserves(address tokenA, address tokenB) public view returns (uint256 reserveA, uint256 reserveB) {
        (address token0,) = sortTokens(tokenA, tokenB);
        (uint256 r0, uint256 r1,) = IPair(pairFor(tokenA, tokenB)).getReserves();
        (reserveA, reserveB) = tokenA == token0 ? (r0, r1) : (r1, r0);
    }

    /// The amount of B worth amountA at the current price (no fee, no price impact).
    function quote(uint256 amountA, uint256 reserveA, uint256 reserveB) public pure returns (uint256) {
        if (amountA == 0) revert InsufficientAmount();
        if (reserveA == 0 || reserveB == 0) revert InsufficientLiquidity();
        return (amountA * reserveB) / reserveA;
    }

    /// Output for an exact input, after the 0.3% fee.
    function getAmountOut(uint256 amountIn, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256) {
        if (amountIn == 0) revert InsufficientInputAmount();
        if (reserveIn == 0 || reserveOut == 0) revert InsufficientLiquidity();
        uint256 amountInWithFee = amountIn * 997;
        return (amountInWithFee * reserveOut) / (reserveIn * 1000 + amountInWithFee);
    }

    /// Input needed for an exact output, after the 0.3% fee (rounded up).
    function getAmountIn(uint256 amountOut, uint256 reserveIn, uint256 reserveOut) public pure returns (uint256) {
        if (amountOut == 0) revert InsufficientOutputAmount();
        if (reserveIn == 0 || reserveOut == 0 || amountOut >= reserveOut) revert InsufficientLiquidity();
        return (reserveIn * amountOut * 1000) / ((reserveOut - amountOut) * 997) + 1;
    }

    function getAmountsOut(uint256 amountIn, address[] calldata path) public view returns (uint256[] memory amounts) {
        if (path.length < 2) revert InvalidPath();
        amounts = new uint256[](path.length);
        amounts[0] = amountIn;
        for (uint256 i; i < path.length - 1; i++) {
            (uint256 rIn, uint256 rOut) = getReserves(path[i], path[i + 1]);
            amounts[i + 1] = getAmountOut(amounts[i], rIn, rOut);
        }
    }

    function getAmountsIn(uint256 amountOut, address[] calldata path) public view returns (uint256[] memory amounts) {
        if (path.length < 2) revert InvalidPath();
        amounts = new uint256[](path.length);
        amounts[amounts.length - 1] = amountOut;
        for (uint256 i = path.length - 1; i > 0; i--) {
            (uint256 rIn, uint256 rOut) = getReserves(path[i - 1], path[i]);
            amounts[i - 1] = getAmountIn(amounts[i], rIn, rOut);
        }
    }

    // ---- token transfers ----

    function _safeTransfer(address token, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0xa9059cbb, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _safeTransferFrom(address token, address from, address to, uint256 value) private {
        (bool ok, bytes memory data) = token.call(abi.encodeWithSelector(0x23b872dd, from, to, value));
        if (!ok || (data.length != 0 && (data.length < 32 || !abi.decode(data, (bool))))) revert TransferFailed();
    }

    function _sendNative(address to, uint256 value) private {
        (bool ok,) = to.call{value: value}("");
        if (!ok) revert NativeTransferFailed();
    }

    /// Wraps `amount` of the native coin and sends it to `pair`.
    function _wrapTo(address pair, uint256 amount) private {
        IWNative(WETH).deposit{value: amount}();
        _safeTransfer(WETH, pair, amount);
    }

    // ---- add liquidity ----

    function _addLiquidity(address tokenA, address tokenB, uint256 amountADesired, uint256 amountBDesired, uint256 amountAMin, uint256 amountBMin)
        private returns (uint256 amountA, uint256 amountB)
    {
        _checkPair(tokenA, tokenB);
        if (IFactory(factory).getPair(tokenA, tokenB) == address(0)) IFactory(factory).createPair(tokenA, tokenB);
        (uint256 reserveA, uint256 reserveB) = getReserves(tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                if (amountBOptimal < amountBMin) revert InsufficientBAmount();
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = quote(amountBDesired, reserveB, reserveA);
                // amountAOptimal <= amountADesired here
                if (amountAOptimal < amountAMin) revert InsufficientAAmount();
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function addLiquidity(
        address tokenA, address tokenB, uint256 amountADesired, uint256 amountBDesired,
        uint256 amountAMin, uint256 amountBMin, address to, uint256 deadline
    ) external ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = pairFor(tokenA, tokenB);
        _safeTransferFrom(tokenA, msg.sender, pair, amountA);
        _safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = IPair(pair).mint(to);
    }

    /// msg.value is the most native coin to add; the rest is refunded.
    function addLiquidityETH(
        address token, uint256 amountTokenDesired, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) external payable ensure(deadline) returns (uint256 amountToken, uint256 amountETH, uint256 liquidity) {
        (amountToken, amountETH) = _addLiquidity(token, WETH, amountTokenDesired, msg.value, amountTokenMin, amountETHMin);
        address pair = pairFor(token, WETH);
        _safeTransferFrom(token, msg.sender, pair, amountToken);
        _wrapTo(pair, amountETH);
        liquidity = IPair(pair).mint(to);
        if (msg.value > amountETH) _sendNative(msg.sender, msg.value - amountETH);
    }

    // ---- remove liquidity ----

    function removeLiquidity(
        address tokenA, address tokenB, uint256 liquidity, uint256 amountAMin, uint256 amountBMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pair = pairFor(tokenA, tokenB);
        if (!IPair(pair).transferFrom(msg.sender, pair, liquidity)) revert TransferFailed();
        (uint256 amount0, uint256 amount1) = IPair(pair).burn(to);
        (address token0,) = sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        if (amountA < amountAMin) revert InsufficientAAmount();
        if (amountB < amountBMin) revert InsufficientBAmount();
    }

    function removeLiquidityETH(
        address token, uint256 liquidity, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(token, WETH, liquidity, amountTokenMin, amountETHMin, address(this), deadline);
        _safeTransfer(token, to, amountToken);
        IWNative(WETH).withdraw(amountETH);
        _sendNative(to, amountETH);
    }

    /// For tokens that take a cut on transfer: passes on whatever token amount the router received.
    function removeLiquidityETHSupportingFeeOnTransferTokens(
        address token, uint256 liquidity, uint256 amountTokenMin, uint256 amountETHMin, address to, uint256 deadline
    ) public ensure(deadline) returns (uint256 amountETH) {
        (, amountETH) = removeLiquidity(token, WETH, liquidity, amountTokenMin, amountETHMin, address(this), deadline);
        _safeTransfer(token, to, IERC20Min(token).balanceOf(address(this)));
        IWNative(WETH).withdraw(amountETH);
        _sendNative(to, amountETH);
    }

    // ---- swaps (exact amounts known up front) ----

    /// amounts[0] must already be in the first pair.
    function _swap(uint256[] memory amounts, address[] calldata path, address _to) private {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < path.length - 2 ? pairFor(output, path[i + 2]) : _to;
            IPair(pairFor(input, output)).swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        _checkPath(path);
        amounts = getAmountsOut(amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactTokens(uint256 amountOut, uint256 amountInMax, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > amountInMax) revert ExcessiveInputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapExactETHForTokens(uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsOut(msg.value, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _wrapTo(pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapTokensForExactETH(uint256 amountOut, uint256 amountInMax, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > amountInMax) revert ExcessiveInputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWNative(WETH).withdraw(amounts[amounts.length - 1]);
        _sendNative(to, amounts[amounts.length - 1]);
    }

    function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline)
        external ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsOut(amountIn, path);
        if (amounts[amounts.length - 1] < amountOutMin) revert InsufficientOutputAmount();
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWNative(WETH).withdraw(amounts[amounts.length - 1]);
        _sendNative(to, amounts[amounts.length - 1]);
    }

    /// msg.value is the most native coin to spend; the rest is refunded.
    function swapETHForExactTokens(uint256 amountOut, address[] calldata path, address to, uint256 deadline)
        external payable ensure(deadline) returns (uint256[] memory amounts)
    {
        if (path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        amounts = getAmountsIn(amountOut, path);
        if (amounts[0] > msg.value) revert ExcessiveInputAmount();
        _wrapTo(pairFor(path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
        if (msg.value > amounts[0]) _sendNative(msg.sender, msg.value - amounts[0]);
    }

    // ---- swaps (fee-on-transfer tokens: amounts measured as they arrive) ----

    function _swapSupportingFeeOnTransferTokens(address[] calldata path, address _to) private {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0,) = sortTokens(input, output);
            IPair pair = IPair(pairFor(input, output));
            uint256 amountOutput;
            {
                (uint256 r0, uint256 r1,) = pair.getReserves();
                (uint256 reserveIn, uint256 reserveOut) = input == token0 ? (r0, r1) : (r1, r0);
                uint256 amountInput = IERC20Min(input).balanceOf(address(pair)) - reserveIn;
                amountOutput = getAmountOut(amountInput, reserveIn, reserveOut);
            }
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOutput) : (amountOutput, uint256(0));
            address to = i < path.length - 2 ? pairFor(output, path[i + 2]) : _to;
            pair.swap(amount0Out, amount1Out, to, new bytes(0));
        }
    }

    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) {
        if (path.length < 2) revert InvalidPath();
        _checkPath(path);
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amountIn);
        address last = path[path.length - 1];
        uint256 before = IERC20Min(last).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        if (IERC20Min(last).balanceOf(to) - before < amountOutMin) revert InsufficientOutputAmount();
    }

    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external payable ensure(deadline) {
        if (path.length < 2 || path[0] != WETH) revert InvalidPath();
        _checkPath(path);
        _wrapTo(pairFor(path[0], path[1]), msg.value);
        address last = path[path.length - 1];
        uint256 before = IERC20Min(last).balanceOf(to);
        _swapSupportingFeeOnTransferTokens(path, to);
        if (IERC20Min(last).balanceOf(to) - before < amountOutMin) revert InsufficientOutputAmount();
    }

    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint256 amountIn, uint256 amountOutMin, address[] calldata path, address to, uint256 deadline
    ) external ensure(deadline) {
        if (path.length < 2 || path[path.length - 1] != WETH) revert InvalidPath();
        _checkPath(path);
        _safeTransferFrom(path[0], msg.sender, pairFor(path[0], path[1]), amountIn);
        // With the precompile, WETH.balanceOf(router) is the router's native
        // balance, which may hold coins of its own: measure the difference.
        uint256 before = IERC20Min(WETH).balanceOf(address(this));
        _swapSupportingFeeOnTransferTokens(path, address(this));
        uint256 amountOut = IERC20Min(WETH).balanceOf(address(this)) - before;
        if (amountOut < amountOutMin) revert InsufficientOutputAmount();
        IWNative(WETH).withdraw(amountOut);
        _sendNative(to, amountOut);
    }
}

